// spec: specs/html-rtl-dir.md (3.3) · кейс: .qa/tests/html-rtl-dir/RTL-DIR-05.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение: не-GET обрываются, SW выключен; фильтр не применяется.
// Регресс #9c4736: двухручковый Radix-слайдер зависит от dir — после глобального RTL ручки не должны поменяться местами
// (#b4b8c9, FILTER-PRICE-03 «ручку Minimum (справа, RTL)»). Мобильный попап покрыт search-filters/price-popup-mobile.spec.ts.
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, openPage, openFilter, thumbs, fields, thumbValue, dragThumb, thumbCenters, PRICE_EDGE,
} from '../search-filters/search-filters.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('html dir=rtl — слайдер цены /search', () => {
  test('Боковой фильтр: Min справа, Max слева, ручка Min тянется влево и увеличивает значение #9c4736 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await openPage(page, '/search');
    const scope = await openFilter(page, false);
    const t = thumbs(scope);
    await expect(t.min).toHaveAttribute('aria-valuenow', '0');
    await expect(t.max).toHaveAttribute('aria-valuenow', String(PRICE_EDGE));

    const { minX, maxX } = await thumbCenters(scope);
    expect(minX, 'RTL: ручка Minimum правее ручки Maximum').toBeGreaterThan(maxX);

    await dragThumb(page, t.min, minX - (minX - maxX) * 0.2);
    const lo = await thumbValue(t.min);
    expect(lo, 'ручка Min после сдвига влево — значение выросло, не инвертировано').toBeGreaterThan(0);
    expect(lo).toBeLessThan(PRICE_EDGE);
    await expect(t.max, 'ручка Max не сдвинулась').toHaveAttribute('aria-valuenow', String(PRICE_EDGE));
    await expect(fields(scope).min, 'поле «מינימום» = значение ручки').toHaveValue(String(lo));
  });
});
